rules.text:
// Every agent may call a read-only tool of low or medium risk.
@id("rg_0001")
permit (principal, action, resource)
when { context.tool.side_effect == "read" && context.tool.risk != "high" };

// A high-risk read runs only when the call is routed through the gateway.
@id("rg_0004")
permit (principal, action, resource)
when {
  context.tool.side_effect == "read" &&
  context.tool.risk == "high" &&
  ["gateway", "contained"].contains(context.tier)
};

// Every agent may write inside a repository that belongs to a-intel.
@id("rg_0007")
permit (principal, action, resource)
when {
  context.tool.side_effect == "write" &&
  context.args has repository &&
  context.args.repository like "a-intel/*"
};

// Harness edits and shell commands are allowed on the agent's own branch.
@id("rg_0009")
permit (
  principal,
  action in [Action::"claude_code__Edit", Action::"claude_code__Bash"],
  resource
)
when { context.args has branch && context.args.branch like "agent/*" };

// Every agent may comment on an issue and update a Linear issue.
@id("rg_0012")
permit (
  principal,
  action in [Action::"github__create_issue_comment", Action::"linear__update_issue"],
  resource
);

// Every agent may post and upload to Slack.
@id("rg_0014")
permit (
  principal,
  action in [Action::"slack__post_message", Action::"slack__upload_file"],
  resource
);

// A post or upload to a shared external Slack channel parks for approval.
@id("rg_0015")
@decision("require_approval")
forbid (
  principal,
  action in [Action::"slack__post_message", Action::"slack__upload_file"],
  resource
)
when { context.args has channel && context.args.channel like "ext-*" }
unless { context.approval.granted };

// A release, a branch delete, or a repository delete on GitHub parks for approval.
@id("rg_0093")
@decision("require_approval")
forbid (
  principal,
  action in [
    Action::"github__create_release",
    Action::"github__delete_branch",
    Action::"github__delete_repository"
  ],
  resource
)
unless { context.approval.granted };

// A pull request may target only a repository that belongs to a-intel.
@id("rg_0024")
forbid (principal, action == Action::"github__create_pull_request", resource)
unless { context.args has repository && context.args.repository like "a-intel/*" };

// A change to a workflow file parks for approval.
@id("rg_0027")
@decision("require_approval")
forbid (
  principal,
  action in [Action::"claude_code__Edit", Action::"github__create_pull_request"],
  resource
)
when { context.args has path && context.args.path like ".github/workflows/*" }
unless { context.approval.granted };

// A change under infra/prod parks for approval.
@id("rg_0029")
@decision("require_approval")
forbid (
  principal,
  action in [Action::"claude_code__Edit", Action::"github__create_pull_request"],
  resource
)
when { context.args has path && context.args.path like "infra/prod/*" }
unless { context.approval.granted };

// A refund above $500 parks for approval.
@id("rg_0031")
@decision("require_approval")
forbid (principal, action == Action::"stripe__create_refund", resource)
when { context.args has amount_cents && context.args.amount_cents > 50000 }
unless { context.approval.granted };

// A payment goes only to a counterparty on the vendor list.
@id("rg_0033")
forbid (principal, action == Action::"stripe__create_payment", resource)
unless { context.args has counterparty && context.args.counterparty like "vendor:*" };

// A payment is denied unless the same run already priced it.
@id("rg_0044")
forbid (principal, action == Action::"stripe__create_payment", resource)
unless { context.run.prior_calls.contains("stripe__list_prices") };

// Money moves only on a weekday between 09:00 and 17:00 UTC.
@id("rg_0035")
forbid (principal, action, resource)
when { context.tool.financial_class == "moves_funds" }
unless {
  context.time.weekday &&
  context.time.hour_utc >= 9 &&
  context.time.hour_utc < 17
};

// A savings plan purchase parks for approval.
@id("rg_0037")
@decision("require_approval")
forbid (principal, action == Action::"aws_billing__purchase_savings_plan", resource)
unless { context.approval.granted };

// Only an agent in finops may call a tool that commits spend.
@id("rg_0038")
forbid (principal, action, resource)
when { context.tool.financial_class == "commits_spend" }
unless { principal in Workspace::"finops" };

// Content fetched from the web may not reach a shell command.
@id("rg_0052")
forbid (principal, action == Action::"claude_code__Bash", resource)
when { context.taint.sources.contains("web") };

// A tainted call may not send anything to a domain outside a-intel.
@id("rg_0053")
forbid (principal, action, resource)
when {
  context.taint.tainted &&
  context.args has recipient_domain &&
  !["a-intel.com", "a-intel.example"].contains(context.args.recipient_domain)
};

// No agent posts to Slack more than 20 times in an hour.
@id("rg_0061")
forbid (principal, action == Action::"slack__post_message", resource)
when { context.rate.calls_last_hour >= 20 };

// No agent fetches from the web more than 60 times in a minute.
@id("rg_0062")
forbid (principal, action == Action::"claude_code__WebFetch", resource)
when { context.rate.calls_last_minute >= 60 };

// A call against prod-east needs an operator with the sre role.
@id("rg_0073")
forbid (principal, action, resource)
when { context.args has cluster && context.args.cluster == "prod-east" }
unless { context.operator.role == "sre" };

// A run with less than $1 of budget left may only read.
@id("rg_0075")
forbid (principal, action, resource)
when { context.budget.remaining_cents < 100 && context.tool.side_effect != "read" };

// A payment larger than what is left on its mandate is denied.
@id("rg_0077")
forbid (principal, action, resource)
when {
  context.tool.financial_class == "moves_funds" &&
  context has mandate &&
  context.args has amount_cents &&
  context.args.amount_cents > context.mandate.remaining_cents
};

// Triage may comment on and label issues in a-intel/mobile.
@id("rg_0081")
permit (
  principal == Agent::"a-intel.core.triage",
  action in [Action::"github__create_issue_comment", Action::"linear__update_issue"],
  resource
)
when { context.args has repository && context.args.repository == "a-intel/mobile" };

// A Snowflake query may not read the raw_pii schema.
@id("rg_0083")
forbid (principal, action == Action::"snowflake__run_query", resource)
when { context.args has schema && context.args.schema == "raw_pii" };

// The docs writer edits files under docs/ and nowhere else.
@id("rg_0085")
forbid (
  principal == Agent::"a-intel.core.docs-writer",
  action == Action::"claude_code__Edit",
  resource
)
unless { context.args has path && context.args.path like "docs/*" };

// A branch delete needs a read of the same branch earlier in the run.
@id("rg_0087")
forbid (principal, action == Action::"github__delete_branch", resource)
unless { context.args has branch && context.run.prior_reads.contains(context.args.branch) };

// A release of a-intel/mobile is cut only from the release branch.
@id("rg_0089")
forbid (principal, action == Action::"github__create_release", resource)
when { context.args has repository && context.args.repository == "a-intel/mobile" }
unless { context.args has branch && context.args.branch == "release" };

// Enrolling a HubSpot contact in a sequence parks for approval.
@id("rg_0101")
@decision("require_approval")
forbid (principal, action == Action::"hubspot__enroll_contact", resource)
unless { context.approval.granted };

// No agent sends email from Salesforce. A person sends it.
@id("rg_0104")
forbid (principal, action == Action::"salesforce__send_email", resource);

// Deleting a pod or draining a node in prod-east parks for approval.
@id("rg_0106")
@decision("require_approval")
forbid (
  principal,
  action in [Action::"kubernetes__delete_pod", Action::"kubernetes__drain_node"],
  resource
)
when { context.args has cluster && context.args.cluster == "prod-east" }
unless { context.approval.granted };

// Support tools may read customer PII fields and may not write them.
@id("rg_0108")
forbid (
  principal,
  action in [
    Action::"zendesk__update_ticket",
    Action::"salesforce__update_contact",
    Action::"hubspot__update_contact"
  ],
  resource
)
when {
  context.args has fields &&
  context.args.fields.containsAny(["email", "phone", "address", "date_of_birth"])
};

// A call that moves more than $1,000 needs two approvers.
@id("rg_0110")
@decision("require_approval")
forbid (principal, action, resource)
when {
  context.tool.financial_class == "moves_funds" &&
  context.args has amount_cents &&
  context.args.amount_cents > 100000
}
unless { context.approval.granted && context.approval.approvers >= 2 };

// Muting a Datadog monitor parks for approval.
@id("rg_0111")
@decision("require_approval")
forbid (principal, action == Action::"datadog__mute_monitor", resource)
unless { context.approval.granted };

// Triage is read-only on a-intel/mobile.
@id("rg_0112")
forbid (principal == Agent::"a-intel.core.triage", action, resource)
when {
  context.args has repository &&
  context.args.repository == "a-intel/mobile" &&
  context.tool.side_effect != "read"
};

// Any write made with tainted input parks for approval.
@id("rg_0115")
@decision("require_approval")
forbid (principal, action, resource)
when { context.taint.tainted && context.tool.side_effect != "read" }
unless { context.approval.granted };

// AWS Billing purchases follow the money window, like every call that moves money.
@id("rg_0116")
forbid (principal, action == Action::"aws_billing__purchase_savings_plan", resource)
unless {
  context.time.weekday &&
  context.time.hour_utc >= 9 &&
  context.time.hour_utc < 17
};

// Every irreversible call in core-platform parks for approval.
@id("rg_0131")
@decision("require_approval")
forbid (principal in Workspace::"core-platform", action, resource)
when { context.tool.side_effect == "irreversible" }
unless { context.approval.granted };
